agentdrills/01-eval-graders/03-triage-fi.solution:
export function fieldWrong(output, field, expected) {
  let parsed;
  try {
    parsed = JSON.parse(output);
  } catch {
    return true;
  }
  if (parsed === null || typeof parsed !== 'object') return true;
  const got = String(parsed[field] ?? '');
  return got !== (expected ?? '');
}

