agentdrills/01-eval-graders/04-rubric-cr.solution:
export const PASS = 0.7;

export function rubricScore(output, rubric) {
  if (rubric.length === 0) return 0;
  const text = output.toLowerCase();
  const met = rubric.filter((c) => text.includes(c.toLowerCase())).length;
  return met / rubric.length;
}

export function rubricFails(output, rubric) {
  return rubricScore(output, rubric) < PASS;
}
